export class Tuner {
  async start(onReading){this.stop();const generation=this.generation;let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});if(generation!==this.generation){stream.getTracks().forEach(t=>t.stop());return;}this.stream=stream;this.ctx=new AudioContext();await this.ctx.resume();if(generation!==this.generation)return;this.source=this.ctx.createMediaStreamSource(stream);this.analyser=this.ctx.createAnalyser();this.analyser.fftSize=8192;this.source.connect(this.analyser);this.worker=new Worker(new URL('./analysis-worker.js',import.meta.url),{type:'module'});this.worker.onmessage=e=>{this.pending=false;onReading(e.data);};this.worker.onerror=()=>{this.pending=false;this.stop();onReading({frequency:0,rms:0,error:true});};this.timer=setInterval(()=>{if(this.pending)return;const raw=new Float32Array(8192);this.analyser.getFloatTimeDomainData(raw);const samples=new Float32Array(4096);for(let i=0;i<4096;i++)samples[i]=(raw[i*2]+raw[i*2+1])/2;this.pending=true;this.worker.postMessage({type:'pitch',samples,rate:this.ctx.sampleRate/2},[samples.buffer]);},70);}catch(e){stream?.getTracks().forEach(t=>t.stop());this.stop();throw e;}}
  stop(){this.generation=(this.generation||0)+1;clearInterval(this.timer);this.worker?.terminate();this.source?.disconnect();this.stream?.getTracks().forEach(t=>t.stop());this.ctx?.close().catch(()=>{});this.ctx=null;this.stream=null;this.pending=false;}
}
